<script>document.addEventListener('DOMContentLoaded',function(){const filters=document.querySelectorAll('.cert-filter'),cards=document.querySelectorAll('.cert-item'),empty=document.querySelector('.cert-no-results');filters.forEach(function(button){button.addEventListener('click',function(){filters.forEach(function(item){item.classList.remove('active')});button.classList.add('active');const selected=button.dataset.filter;let visible=0;cards.forEach(function(card){const show=selected==='all'||card.dataset.category===selected;card.hidden=!show;if(show)visible++});if(empty)empty.hidden=visible!==0})})});</script>
